begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select plan(560);

-- Seven additive domain tables and coexistence.
select has_table('public',t,t||' exists')from(values('receivables'),('debt_payments_v2'),('debt_allocations'),('settlement_entries'),('settlement_periods'),('settlement_acts'),('settlement_act_lines'))x(t);
select has_table('public','debt_payments','legacy debt_payments remains');
select ok((select relrowsecurity from pg_class where oid=format('public.%I',t)::regclass),t||' RLS enabled')from(values('receivables'),('debt_payments_v2'),('debt_allocations'),('settlement_entries'),('settlement_periods'),('settlement_acts'),('settlement_act_lines'))x(t);
select ok(not has_table_privilege('anon',format('public.%I',t),'SELECT,INSERT,UPDATE,DELETE'),'anon denied '||t)from(values('receivables'),('debt_payments_v2'),('debt_allocations'),('settlement_entries'),('settlement_periods'),('settlement_acts'),('settlement_act_lines'))x(t);
select ok(not has_table_privilege('authenticated',format('public.%I',t),'INSERT,UPDATE,DELETE'),'browser writes denied '||t)from(values('receivables'),('debt_payments_v2'),('debt_allocations'),('settlement_entries'),('settlement_periods'),('settlement_acts'),('settlement_act_lines'))x(t);
select ok(has_table_privilege('authenticated',format('public.%I',t),'SELECT'),'authenticated SELECT via RLS '||t)from(values('receivables'),('debt_payments_v2'),('debt_allocations'),('settlement_entries'),('settlement_periods'),('settlement_acts'),('settlement_act_lines'))x(t);

-- Permission registry is exact after 0015.
select is((select count(*)from permissions),51::bigint,'permission registry 51');
select is((select count(*)from permissions where critical),9::bigint,'critical permissions 9');
select is((select count(*)from permission_profile_permissions where permission_profile_id='00000000-0000-0000-0000-000000000101'),51::bigint,'owner profile 51');
select is((select count(*)from permission_profile_permissions where permission_profile_id='00000000-0000-0000-0000-000000000102'),16::bigint,'seller profile remains 16');
select set_eq($$select code from permissions where critical$$,$$select * from(values('purchases.reverse'),('sales.reverse'),('sales.discount.override'),('debts.limit.override'),('cash.move.override'),('support.access.approve'),('debts.reverse'),('debts.write_off'),('settlements.close'))x(code)$$,'critical permission set exact');
select ok(exists(select 1 from permissions where code=p and module=m and critical),p||' registered critical')from(values('debts.reverse','debts'),('debts.write_off','debts'),('settlements.close','settlements'))x(p,m);
select ok(exists(select 1 from permission_profile_permissions x join permissions p on p.id=x.permission_id where x.permission_profile_id='00000000-0000-0000-0000-000000000101'and p.code=c),'owner receives '||c)from(values('debts.reverse'),('debts.write_off'),('settlements.close'))x(c);
select ok(not exists(select 1 from permission_profile_permissions x join permissions p on p.id=x.permission_id where x.permission_profile_id='00000000-0000-0000-0000-000000000102'and p.code=c),'seller denied '||c)from(values('debts.reverse'),('debts.write_off'),('settlements.close'))x(c);

-- Public command and safe read API signatures.
select has_function('public',f,args,f||' exists')from(values
 ('v2_record_debt_payment',array['uuid','uuid','uuid','uuid','uuid','text','date','character','uuid','uuid','timestamp with time zone','jsonb','jsonb']),
 ('v2_write_off_receivable',array['uuid','numeric','text','uuid','uuid']),
 ('v2_reverse_receivable_write_off',array['uuid','uuid','uuid','jsonb']),
 ('v2_close_settlement_period',array['uuid','uuid','character','date','date','text','uuid','uuid','uuid']),
 ('v2_receivable_journal',array['uuid','uuid']),('v2_debt_payment_journal',array['uuid','uuid']),
 ('v2_settlement_journal',array['uuid','uuid','character']),('v2_counterparty_balance',array['uuid','uuid','character']),
 ('v2_settlement_act',array['uuid']),('v2_recompute_receivable',array['uuid']),
 ('v2_can_view_debt',array['uuid','uuid']),('v2_can_view_settlement',array['uuid','uuid','text']),
 ('v2_guard_receivable',array[]::text[]),('v2_guard_debt_payment',array[]::text[]),('v2_guard_settlement_entry',array[]::text[])
)x(f,args);
select ok(has_function_privilege('authenticated',format('public.%I(%s)',f,args),'EXECUTE'),'authenticated executes '||f)from(values
 ('v2_record_debt_payment','uuid,uuid,uuid,uuid,uuid,text,date,character,uuid,uuid,timestamptz,jsonb,jsonb'),
 ('v2_write_off_receivable','uuid,numeric,text,uuid,uuid'),('v2_reverse_receivable_write_off','uuid,uuid,uuid,jsonb'),
 ('v2_close_settlement_period','uuid,uuid,character,date,date,text,uuid,uuid,uuid'),
 ('v2_receivable_journal','uuid,uuid'),('v2_debt_payment_journal','uuid,uuid'),('v2_settlement_journal','uuid,uuid,character'),
 ('v2_counterparty_balance','uuid,uuid,character'),('v2_settlement_act','uuid'))x(f,args);
select ok(not has_function_privilege('authenticated',format('public.%I(%s)',f,args),'EXECUTE'),'internal denied '||f)from(values
 ('v2_debt_context_required',''),('v2_settlement_context_required',''),('v2_financial_append_only',''),
 ('v2_guard_receivable',''),('v2_guard_debt_payment',''),('v2_guard_debt_allocation',''),('v2_guard_settlement_entry',''),
 ('v2_guard_settlement_period',''),('v2_guard_settlement_snapshot',''),('v2_recompute_receivable','uuid'),
 ('v2_purchase_settlement_entry',''))x(f,args);

-- Named defensive constraints.
select ok(exists(select 1 from pg_constraint where conrelid=format('public.%I',t)::regclass and conname=n),t||'.'||n)from(values
 ('receivables','receivables_amount_check'),('receivables','receivables_currency_check'),('receivables','receivables_status_check'),('receivables','receivables_state_check'),
 ('debt_payments_v2','debt_payments_v2_number_check'),('debt_payments_v2','debt_payments_v2_amount_check'),('debt_payments_v2','debt_payments_v2_currency_check'),('debt_payments_v2','debt_payments_v2_status_check'),
 ('debt_allocations','debt_allocations_type_check'),('debt_allocations','debt_allocations_source_check'),('debt_allocations','debt_allocations_sign_check'),
 ('settlement_entries','settlement_entries_type_check'),('settlement_entries','settlement_entries_amount_check'),('settlement_entries','settlement_entries_currency_check'),('settlement_entries','settlement_entries_source_check'),
 ('settlement_periods','settlement_periods_currency_check'),('settlement_periods','settlement_periods_range_check'),('settlement_periods','settlement_periods_status_check'),('settlement_periods','settlement_periods_state_check'),
 ('settlement_acts','settlement_acts_hash_check'))x(t,n);

-- Required FK targets.
select ok(exists(select 1 from pg_constraint c join pg_attribute a on a.attrelid=c.conrelid and a.attnum=any(c.conkey)where c.contype='f'and c.conrelid=format('public.%I',t)::regclass and a.attname=col and c.confrelid=format('public.%I',target)::regclass),t||'.'||col||' -> '||target)from(values
 ('receivables','sale_id','sales_v2'),('receivables','counterparty_id','counterparties'),('receivables','command_id','command_log'),
 ('debt_payments_v2','shift_id','shifts_v2'),('debt_payments_v2','device_id','devices_v2'),('debt_payments_v2','reversal_of_id','debt_payments_v2'),
 ('payments_v2','debt_payment_id','debt_payments_v2'),('debt_allocations','receivable_id','receivables'),
 ('settlement_acts','settlement_period_id','settlement_periods'),('settlement_act_lines','settlement_entry_id','settlement_entries'))x(t,col,target);

-- Contract indexes.
select ok(exists(select 1 from pg_indexes where schemaname='public'and tablename=t and indexname=n),n||' exists')from(values
 ('receivables','receivables_journal_idx'),('receivables','receivables_branch_idx'),('receivables','receivables_overdue_idx'),
 ('debt_payments_v2','debt_payments_v2_one_reversal'),('debt_payments_v2','debt_payments_v2_journal_idx'),('debt_payments_v2','debt_payments_v2_shift_idx'),
 ('debt_allocations','debt_allocations_receivable_idx'),('debt_allocations','debt_allocations_reversal_key'),
 ('settlement_entries','settlement_entries_primary_key'),('settlement_entries','settlement_entries_reversal_key'),('settlement_entries','settlement_entries_journal_idx'),
 ('settlement_periods','settlement_periods_one_correction'),('settlement_periods','settlement_periods_journal_idx'),
 ('payments_v2','payments_v2_debt_payment_idx'),('sales_v2','sales_v2_journal_idx'))x(t,n);

-- Essential column matrix (100 assertions).
with expected(t,c)as(values
 ('receivables','id'),('receivables','organization_id'),('receivables','branch_id'),('receivables','counterparty_id'),('receivables','sale_id'),('receivables','original_amount'),('receivables','outstanding_amount'),('receivables','currency_code'),('receivables','due_date'),('receivables','status'),('receivables','version'),('receivables','created_by'),('receivables','command_id'),('receivables','created_at'),('receivables','closed_at'),
 ('debt_payments_v2','id'),('debt_payments_v2','organization_id'),('debt_payments_v2','branch_id'),('debt_payments_v2','register_id'),('debt_payments_v2','counterparty_id'),('debt_payments_v2','shift_id'),('debt_payments_v2','document_number'),('debt_payments_v2','business_date'),('debt_payments_v2','total_amount'),('debt_payments_v2','currency_code'),('debt_payments_v2','status'),('debt_payments_v2','device_id'),('debt_payments_v2','local_operation_id'),('debt_payments_v2','client_created_at'),('debt_payments_v2','posted_by'),('debt_payments_v2','posted_at'),('debt_payments_v2','reversal_of_id'),('debt_payments_v2','command_id'),('debt_payments_v2','created_at'),
 ('debt_allocations','id'),('debt_allocations','organization_id'),('debt_allocations','receivable_id'),('debt_allocations','debt_payment_id'),('debt_allocations','sale_return_id'),('debt_allocations','sale_reversal_id'),('debt_allocations','allocation_type'),('debt_allocations','amount'),('debt_allocations','reversal_of_id'),('debt_allocations','command_id'),('debt_allocations','approval_request_id'),('debt_allocations','created_by'),('debt_allocations','created_at'),
 ('settlement_entries','id'),('settlement_entries','organization_id'),('settlement_entries','branch_id'),('settlement_entries','counterparty_id'),('settlement_entries','entry_type'),('settlement_entries','amount_delta'),('settlement_entries','currency_code'),('settlement_entries','business_date'),('settlement_entries','source_document_type'),('settlement_entries','source_document_id'),('settlement_entries','reversal_of_id'),('settlement_entries','command_id'),('settlement_entries','approval_request_id'),('settlement_entries','created_by'),('settlement_entries','created_at'),
 ('settlement_periods','id'),('settlement_periods','organization_id'),('settlement_periods','counterparty_id'),('settlement_periods','currency_code'),('settlement_periods','starts_on'),('settlement_periods','ends_on'),('settlement_periods','status'),('settlement_periods','opening_balance'),('settlement_periods','closing_balance'),('settlement_periods','closed_by'),('settlement_periods','closed_at'),('settlement_periods','corrected_period_id'),('settlement_periods','created_by'),('settlement_periods','command_id'),('settlement_periods','created_at'),
 ('settlement_acts','id'),('settlement_acts','organization_id'),('settlement_acts','settlement_period_id'),('settlement_acts','act_number'),('settlement_acts','total_debit'),('settlement_acts','total_credit'),('settlement_acts','closing_balance'),('settlement_acts','snapshot_hash'),('settlement_acts','schema_version'),('settlement_acts','created_by'),('settlement_acts','command_id'),('settlement_acts','created_at'),
 ('settlement_act_lines','id'),('settlement_act_lines','organization_id'),('settlement_act_lines','settlement_act_id'),('settlement_act_lines','settlement_entry_id'),('settlement_act_lines','line_number'),('settlement_act_lines','amount_delta'),('settlement_act_lines','created_at'),
 ('payments_v2','debt_payment_id'),('sales_v2','debt_amount'),('sale_returns','debt_reduction_amount'))
select ok(exists(select 1 from information_schema.columns where table_schema='public'and table_name=t and column_name=c),t||'.'||c||' exists')from expected;

-- Trigger inventory (15 assertions).
select ok(exists(select 1 from pg_trigger where tgrelid=format('public.%I',t)::regclass and tgname=n and not tgisinternal),n||' installed')from(values
 ('receivables','v2_receivables_context'),('receivables','v2_receivables_guard'),('debt_payments_v2','v2_debt_payments_context'),('debt_payments_v2','v2_debt_payments_guard'),
 ('debt_allocations','v2_debt_allocations_context'),('debt_allocations','v2_debt_allocations_guard'),('debt_allocations','v2_debt_allocations_append_only'),
 ('settlement_entries','v2_settlement_entries_context'),('settlement_entries','v2_settlement_entries_guard'),('settlement_entries','v2_settlement_entries_append_only'),
 ('settlement_periods','v2_settlement_periods_context'),('settlement_periods','v2_settlement_periods_guard'),
 ('settlement_acts','v2_settlement_acts_append_only'),('settlement_act_lines','v2_settlement_act_lines_guard'),('settlement_act_lines','v2_settlement_act_lines_append_only'))x(t,n);

-- One SELECT policy for every new table.
select ok(exists(select 1 from pg_policies where schemaname='public'and tablename=t and cmd='SELECT'),'SELECT policy '||t)from(values('receivables'),('debt_payments_v2'),('debt_allocations'),('settlement_entries'),('settlement_periods'),('settlement_acts'),('settlement_act_lines'))x(t);

-- Legacy/V2 separation remains explicit.
select ok('public.debt_payments'::regclass<>'public.debt_payments_v2'::regclass,'legacy and V2 debt payments are distinct relations');
select ok(not exists(select 1 from pg_constraint where conrelid='public.debt_payments'::regclass and confrelid='public.debt_payments_v2'::regclass),'legacy debt payments has no V2 FK');
select ok(exists(select 1 from pg_constraint where conrelid='public.payments_v2'::regclass and confrelid='public.debt_payments_v2'::regclass),'V2 payments points to V2 debt payments');
select ok(not exists(select 1 from public.debt_payments_v2),'no automatic legacy backfill');

-- Behavioral debt-sale and debt-first-return fixture ------------------------
select has_function('public','v2_post_sale',array['uuid','uuid','uuid','uuid','uuid','uuid','text','date','character','uuid','uuid','timestamp with time zone','jsonb','jsonb','uuid','jsonb'],'debt-aware sale overload exists');
